{
    int syscall_num = regs->syscallno;
    struct syscall_metadata *metadata;

    if (syscall_num < 0 || syscall_num >= MAX_SYSCALLS)
        return;

    metadata = get_syscall_metadata(syscall_num);
    if (!metadata || !metadata->enabled)
        return;

    if (!metadata->exit_event)
        return;

